export default function HeroPuzzle() {
  const router = useRouter()
  const go = (event, href) => {
    event.preventDefault()
    router.push(href)
  }

  return (
    <div className='ob-puzzle'>
      <svg
        viewBox='0 0 2048 989'
        preserveAspectRatio='xMidYMid slice'
        aria-hidden='true'
        focusable='false'>
        {PIECES.map(piece => (
          <a
            key={piece.key}
            href={piece.href}
            aria-label={piece.name}
            onClick={event => go(event, piece.href)}>
            <path d={piece.d} vectorEffect='nonScalingStroke' />
            <text
              x={piece.x}
              y={piece.y}
              textAnchor={piece.anchor}
              className={`ob-puzzle-label ob-puzzle-label-desk ob-puzzle-label-${piece.key}`}>
              {piece.name}
            </text>
            <text
              x={piece.mx}
              y={piece.my}
              textAnchor={piece.anchor}
              className={`ob-puzzle-label ob-puzzle-label-mobi ob-puzzle-label-${piece.key}`}>
              {piece.name}
            </text>
          </a>
        ))}
        <path className='ob-hand-outline' d={HAND_OUTLINE} vectorEffect='nonScalingStroke' />
      </svg>
      <style jsx>{`
        .ob-puzzle {
          position: absolute;
          inset: 0;
          z-index: 20;
          pointer-events: none;
        }
        .ob-puzzle :global(svg) {
          position: absolute;
          inset: 0;
          width: 100%;
          height: 100%;
          display: block;
        }
        .ob-puzzle :global(a path) {
          fill: rgba(255, 248, 235, 0.12);
          stroke: rgba(201, 166, 107, 0.38);
          stroke-width: 1.1;
          vector-effect: non-scaling-stroke;
          transition: fill 220ms ease, stroke 220ms ease;
          pointer-events: auto;
          cursor: pointer;
        }
        .ob-puzzle :global(a:hover path),
        .ob-puzzle :global(a:focus-visible path) {
          fill: rgba(201, 166, 107, 0.2);
          stroke: rgba(212, 175, 55, 0.88);
        }
        .ob-puzzle :global(.ob-hand-outline) {
          fill: none;
          stroke: rgba(201, 166, 107, 0.82);
          stroke-width: 1.7;
          vector-effect: non-scaling-stroke;
          pointer-events: none;
        }
        .ob-puzzle :global(.ob-puzzle-label) {
          fill: rgba(44, 36, 28, 0.9);
          font-size: 28px;
          letter-spacing: 6px;
          font-weight: 400;
          font-family: inherit;
          pointer-events: none;
          paint-order: stroke;
          stroke: rgba(255, 244, 220, 0.5);
          stroke-width: 4px;
        }
        .ob-puzzle :global(.ob-puzzle-label-mobi) {
          display: none;
        }
        .ob-puzzle :global(.ob-puzzle-label-dao),
        .ob-puzzle :global(.ob-puzzle-label-shu) {
          font-size: 34px;
          letter-spacing: 10px;
        }
        @media (max-width: 767px) {
          .ob-puzzle :global(.ob-puzzle-label-desk) {
            display: none;
          }
          .ob-puzzle :global(.ob-puzzle-label-mobi) {
            display: inline;
          }
          .ob-puzzle :global(.ob-puzzle-label) {
            font-size: 18px;
            letter-spacing: 2px;
            stroke-width: 3px;
          }
          .ob-puzzle :global(.ob-puzzle-label-dao),
          .ob-puzzle :global(.ob-puzzle-label-shu) {
            font-size: 22px;
            letter-spacing: 4px;
          }
        }
        @media (hover: none) {
          .ob-puzzle :global(a:hover path) {
            fill: rgba(255, 248, 235, 0.12);
            stroke: rgba(201, 166, 107, 0.38);
          }
        }
      `}</style>
    </div>
  )
}
